import { test, expect } from '@playwright/test';

test.describe('Invalid Card Number Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display error message when entering invalid card number', async ({ page }) => {
    // Locate and fill card number input using getByLabel
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('123');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid card number/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message has correct styling
    const errorBox = page.locator('[data-testid="error-box"]');
    await expect(errorBox).toBeVisible();
    await expect(errorBox).toHaveClass(/error-message/);

    // Verify form is not submitted
    const paymentForm = page.locator('[data-testid="payment-form"]');
    await expect(paymentForm).toBeVisible();
  });

  test('should clear error message when entering valid card number', async ({ page }) => {
    // Locate and fill invalid card number
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('123');

    // Locate and click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid card number/i);
    await expect(errorMessage).toBeVisible();

    // Locate and clear the invalid card number
    await cardNumberInput.clear();
    await cardNumberInput.fill('4121 1276 1210 1211');

    // Locate and click submit button again
    await submitButton.click();

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/payment successful/i);
    await expect(successMessage).toBeVisible();

    // Verify form is submitted
    const paymentForm = page.locator('[data-testid="payment-form"]');
    await expect(paymentForm).toHaveAttribute('data-submitted', 'true');
  });
});
